    try {
        int length = str.length();
        if (length > lb.getRemaining()) {
            lb = session.getAllocator().allocate(length);
        }
        for (int i = 0; i < length; i++) {
            char c = str.charAt(i);
            if (c <= 0x7F) {
                lb.append((byte) c);
            } else if (c <= 0x7FF) {
                lb.append((byte) (0xC0 | (c >> 6)));
                lb.append((byte) (0x80 | (c & 0x3F)));
            } else if (c <= 0xFFFF) {
                lb.append((byte) (0xE0 | (c >> 12)));
                lb.append((byte) (0x80 | ((c >> 6) & 0x3F)));
                lb.append((byte) (0x80 | (c & 0x3F)));
            } else {
                lb.append((byte) (0xF0 | (c >> 18)));
                lb.append((byte) (0x80 | ((c >> 12) & 0x3F)));
                lb.append((byte) (0x80 | ((c >> 6) & 0x3F)));
                lb.append((byte) (0x80 | (c & 0x3F)));
